/**
 * Props for {@link ProductSwitch}
 */
export type ProductSwitchProps = {
  regionSwitchRegionLanguage?: React.ReactNode;
  regionSwitchRegionVariant?: "Light" | "Dark";
  regionSwitchVariant?: "right-aligned" | "left-aligned";
  variant?: "Base" | "Business";
};

/**
 * ProductSwitch
 *
 * @see {@link https://grey-lp.design.webflow.com | Source site in Webflow}
 */
export function ProductSwitch({
  regionSwitchRegionLanguage = "EN",
  regionSwitchRegionVariant = "Light",
  regionSwitchVariant = "right-aligned",
  variant = "Base",
}: ProductSwitchProps) {
  _interactions.useInteractions(_interactionsData);

  const _styleVariantMap = {
    Base: "",
    Business: "w-variant-97368726-cc9f-f1f2-74f7-27d91f270ca9",
  };

  const _activeStyleVariant = _styleVariantMap[variant];

  return (
    <div
      className={DEVLINK_SCOPE_CLASS}
      style={{
        display: "contents",
      }}
    >
      <Section
        className={`audience-switch ${_activeStyleVariant}`}
        data-w-id={"a0bc233a-e51d-da5a-2cec-9ca690bf95bb"}
        grid={{
          type: "section",
        }}
        tag={"div"}
      >
        <Block
          className={`product_region-wrapper ${_activeStyleVariant}`}
          tag={"div"}
        >
          <Block
            className={`product-wrapper ${_activeStyleVariant}`}
            tag={"div"}
          >
            <Link
              button={false}
              className={`product-link ${_activeStyleVariant}`}
              options={{
                href: "/",
              }}
            >
              {"For Individuals"}
            </Link>
            <Link
              button={false}
              className={`product-link ${_activeStyleVariant}`}
              options={{
                href: "/business",
              }}
            >
              {"For Businesses"}
            </Link>
          </Block>
          <RegionSwitch
            regionLanguage={regionSwitchRegionLanguage}
            regionVariant={regionSwitchRegionVariant}
            variant={regionSwitchVariant}
          />
        </Block>
      </Section>
    </div>
  );
}
